#!/usr/bin/env bash
set -euo pipefail
BASE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")"&&pwd)"; source "$BASE_DIR/lib/ui.sh"; require_root; ui_header; printf '\n  This removes local Pterodactyl/Wings application files and service configs.\n  Database destruction is intentionally not automatic.\n\n'; read -r -p '  Type UNINSTALL to continue › ' c; [[ $c == UNINSTALL ]]|| { ui_warning 'Cancelled.';exit 0; }; PANEL_DIR="${PTERODACTYL_DIRECTORY:-/var/www/pterodactyl}"; systemctl disable --now wings pteroq 2>/dev/null||true; rm -f /etc/systemd/system/wings.service /etc/systemd/system/pteroq.service; systemctl daemon-reload 2>/dev/null||true; rm -f /etc/nginx/sites-enabled/pterodactyl.conf /etc/nginx/sites-available/pterodactyl.conf; rm -rf -- "$PANEL_DIR"; rm -f /usr/local/bin/wings; rm -rf -- /etc/pterodactyl; ui_success 'Local panel/Wings files removed.'; ui_warning 'MariaDB/Redis data and DNS were preserved.'
